1	// Package rollup downsamples a time series into fixed windows aligned to
2	// the Unix epoch, and merges rollups that share a window size.
3	//
4	// A Roller is safe for concurrent use: samples may be filed, windows read,
5	// and rollers merged from multiple goroutines at once. Every read observes
6	// an internally consistent snapshot, and a merge or batch is visible to
7	// other callers either in full or not at all.
8	//
9	// A Counter offers the same guarantees for a cumulative counter that may
10	// reset: it derives increments from successive readings and reports their
11	// per-window sums and rates.
12	package rollup
13	
14	import (
15		"errors"
16		"math"
17		"math/big"
18		"math/bits"
19		"sort"
20		"sync"
21		"sync/atomic"
22		"time"
23	)
24	
25	// ErrOutOfOrder is returned by Add when a sample predates the most recent
26	// sample the roller has already accepted.
27	var ErrOutOfOrder = errors.New("rollup: out of order")
28	
29	// ErrWindowMismatch is returned by Merge when the two rollers use different
30	// window sizes.
31	var ErrWindowMismatch = errors.New("rollup: window mismatch")
32	
33	// ErrNonFinite is returned by Add and AddBatch when a sample value is NaN
34	// or an infinity. Such a sample is never filed: on Add the roller is left
35	// unchanged, and on AddBatch the whole batch is rejected as one unit.
36	var ErrNonFinite = errors.New("rollup: non-finite value")
37	
38	// Sample is one record in a batch passed to AddBatch: a value observed at
39	// one instant.
40	type Sample struct {
41		At    time.Time
42		Value float64
43	}
44	
45	// Window holds the aggregate statistics of the samples filed into one
46	// window. Start is the window's left-closed, right-open lower bound.
47	type Window struct {
48		Start time.Time
49		Count int64
50		Sum   float64
51		Min   float64
52		Max   float64
53	}
54	
55	// backWindow pairs a backfilled window with its exact bookkeeping.
56	type backWindow struct {
57		w  Window
58		st stats
59	}
60	
61	// Roller aggregates samples into fixed windows of a single size.
62	//
63	// The zero value is not usable; build one with New. All methods are safe
64	// to call concurrently from multiple goroutines.
65	type Roller struct {
66		// mu guards buckets, bstats, back, latest, and hasAny. window and id
67		// are fixed at construction and read without the lock.
68		//
69		// buckets and bstats are parallel flat slices kept sorted by window
70		// start: samples arrive in non-decreasing time order, so Add appends
71		// in amortized constant time, Windows reads out without re-sorting,
72		// and Merge is a single linear pass over both sides.
73		//
74		// back holds backfilled windows keyed by window start: a sample that
75		// lands before the newest window opens its bucket here, so a new
76		// window costs one map insert instead of shifting a sorted tail and a
77		// mass backfill stays linear. Once the number of backfilled windows
78		// catches up with buckets, they are sorted once and folded into it,
79		// amortizing that sort over the inserts. Every read consults both
80		// buckets and back, and no window start appears in both at the same
81		// time.
82		mu      sync.RWMutex
83		id      uint64
84		window  time.Duration
85		buckets []Window
86		bstats  []stats
87		back    map[time.Time]backWindow
88		latest  time.Time
89		hasAny  bool
90	}
91	
92	// idGen hands out unique roller IDs so Merge can lock two rollers in a
93	// consistent order and concurrent cross-merges cannot deadlock.
94	var idGen atomic.Uint64
95	
96	// New builds a roller with the given window size. It panics with
97	// "rollup: bad window" if window is not positive.
98	func New(window time.Duration) *Roller {
99		if window <= 0 {
100			panic("rollup: bad window")
101		}
102		return &Roller{
103			id:     idGen.Add(1),
104			window: window,
105		}
106	}
107	
108	// startOf returns the start of the window containing at, aligned to an
109	// integer multiple of the window size since the Unix epoch.
110	func (r *Roller) startOf(at time.Time) time.Time {
111		return alignStart(at, r.window.Nanoseconds())
112	}
113	
114	// alignStart returns the start of the window of width w nanoseconds
115	// containing at, aligned to an integer multiple of w since the Unix epoch.
116	// The arithmetic is exact for any time value, including ones whose
117	// nanosecond offset from the epoch does not fit in an int64.
118	func alignStart(at time.Time, w int64) time.Time {
119		sec := at.Unix()
120		nsec := int64(at.Nanosecond())
121		if sec >= -9223372036 && sec <= 9223372035 {
122			// sec*1e9+nsec fits in an int64. Rounding a negative ns down to
123			// a window multiple can reach ns-(w-1), so stay on the fast
124			// path only when that product cannot overflow either.
125			if ns := sec*1e9 + nsec; ns >= math.MinInt64+w-1 {
126				start := ns / w
127				if ns%w != 0 && ns < 0 {
128					start--
129				}
130				return time.Unix(0, start*w).UTC()
131			}
132		}
133		return windowStartWide(sec, nsec, w)
134	}
135	
136	// windowStartWide is the 128-bit slow path of alignStart, for times whose
137	// nanosecond offset from the epoch overflows an int64.
138	func windowStartWide(sec, nsec, w int64) time.Time {
139		// t = sec*1e9 + nsec as a 128-bit two's-complement value (hi, lo).
140		uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
141		if sec < 0 {
142			uhi -= 1e9
143		}
144		hi := int64(uhi)
145		lo := ulo + uint64(nsec)
146		if lo < ulo {
147			hi++
148		}
149		// Round t down to a multiple of w: start = t - floorMod(t, w).
150		rem := floorMod128(hi, lo, w)
151		if lo < rem {
152			hi--
153		}
154		lo -= rem
155		// Split start into whole seconds and nanoseconds.
156		ns := floorMod128(hi, lo, 1e9)
157		if lo < ns {
158			hi--
159		}
160		lo -= ns
161		return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
162	}
163	
164	// floorMod128 returns t mod y for the signed 128-bit value t = (hi<<64)|lo
165	// and positive y, with the result in [0, y).
166	func floorMod128(hi int64, lo uint64, y int64) uint64 {
167		yu := uint64(y)
168		if hi >= 0 {
169			return rem128(uint64(hi), lo, yu)
170		}
171		// Negate the 128-bit value, take the remainder, and reflect it back
172		// into [0, y) for floored (not truncated) division.
173		mlo := -lo
174		mhi := -uint64(hi)
175		if lo != 0 {
176			mhi--
177		}
178		if r := rem128(mhi, mlo, yu); r != 0 {
179			return yu - r
180		}
181		return 0
182	}
183	
184	// quo128 returns (hi<<64|lo)/y for a signed 128-bit dividend known to be an
185	// exact multiple of y, with a quotient that fits in an int64.
186	func quo128(hi int64, lo uint64, y int64) int64 {
187		yu := uint64(y)
188		if hi >= 0 {
189			q, _ := bits.Div64(uint64(hi), lo, yu)
190			return int64(q)
191		}
192		mlo := -lo
193		mhi := -uint64(hi)
194		if lo != 0 {
195			mhi--
196		}
197		q, _ := bits.Div64(mhi, mlo, yu)
198		return -int64(q)
199	}
200	
201	// rem128 returns (hi<<64 | lo) mod y for unsigned hi, lo and y > 0.
202	func rem128(hi, lo, y uint64) uint64 {
203		if hi >= y {
204			hi %= y
205		}
206		return bits.Rem64(hi, lo, y)
207	}
208	
209	// windowIndex locates the window starting at start in ws, which must be
210	// sorted by window start. The second result reports whether it exists;
211	// when it does not, the index is where it would be inserted to keep ws
212	// sorted, i.e. the first window whose start is not before start.
213	func windowIndex(ws []Window, start time.Time) (int, bool) {
214		sec, nsec := start.Unix(), int64(start.Nanosecond())
215		lo, hi := 0, len(ws)
216		for lo < hi {
217			m := int(uint(lo+hi) >> 1)
218			s := ws[m].Start
219			if ss, sn := s.Unix(), int64(s.Nanosecond()); ss < sec || (ss == sec && sn < nsec) {
220				lo = m + 1
221			} else {
222				hi = m
223			}
224		}
225		if lo < len(ws) {
226			if s := ws[lo].Start; s.Unix() == sec && int64(s.Nanosecond()) == nsec {
227				return lo, true
228			}
229		}
230		return lo, false
231	}
232	
233	// ensureStatsLocked grows bstats to match buckets and seeds bookkeeping
234	// for windows assembled without it. It costs nothing once the two slices
235	// are already in step, which they always are on the normal write paths.
236	func (r *Roller) ensureStatsLocked() {
237		if len(r.bstats) >= len(r.buckets) {
238			return
239		}
240		grown := make([]stats, len(r.buckets))
241		copy(grown, r.bstats)
242		for i := len(r.bstats); i < len(r.buckets); i++ {
243			grown[i].absorb(r.buckets[i])
244		}
245		r.bstats = grown
246	}
247	
248	// Add files a sample into its window. A non-finite value (NaN or an
249	// infinity) is rejected with ErrNonFinite. A sample earlier than the most
250	// recent accepted sample is rejected with ErrOutOfOrder. In either case
251	// the roller, including its most-recent marker, is left unchanged; a
252	// sample at the same instant as the marker is accepted and counted again.
253	//
254	// Concurrent Adds are serialized: each takes effect in the order it
255	// acquires the roller, and the out-of-order check is measured against the
256	// samples accepted before it in that order.
257	func (r *Roller) Add(at time.Time, value float64) error {
258		if math.IsNaN(value) || math.IsInf(value, 0) {
259			return ErrNonFinite
260		}
261		r.mu.Lock()
262		defer r.mu.Unlock()
263		if r.hasAny && at.Before(r.latest) {
264			return ErrOutOfOrder
265		}
266		r.ensureStatsLocked()
267		r.fileLocked(at, value)
268		r.latest = at
269		r.hasAny = true
270		return nil
271	}
272	
273	// AddBatch files a batch of samples as one atomic unit: either every
274	// sample takes effect or none does. The samples may arrive in any order
275	// and are not checked against each other; several samples at the same
276	// instant are each counted. Each sample is filed into its epoch-aligned
277	// window exactly as Add would file it.
278	//
279	// A batch holding any non-finite value is rejected with ErrNonFinite. If
280	// any sample predates the most recent sample the roller has already
281	// accepted, the whole batch is rejected with ErrOutOfOrder. Either kind of
282	// rejection leaves the roller and its most-recent marker unchanged.
283	// Otherwise the marker advances to the later of its previous value and the
284	// newest sample in the batch. A nil or empty batch is accepted, changes
285	// nothing, and does not advance the marker.
286	//
287	// The batch is atomic with respect to every other call on the roller:
288	// concurrent adds, batches, merges, range reads, and cursor creation
289	// observe the roller wholly before or wholly after the batch.
290	func (r *Roller) AddBatch(samples []Sample) error {
291		if len(samples) == 0 {
292			return nil
293		}
294		// Finiteness is a property of each value and is scanned across the
295		// whole batch first, so one NaN rejects the unit even when a stale
296		// sample sits earlier in the slice. Nothing is filed until the batch
297		// is fully validated.
298		for _, s := range samples {
299			if math.IsNaN(s.Value) || math.IsInf(s.Value, 0) {
300				return ErrNonFinite
301			}
302		}
303		r.mu.Lock()
304		defer r.mu.Unlock()
305		latest := samples[0].At
306		for _, s := range samples {
307			if r.hasAny && s.At.Before(r.latest) {
308				return ErrOutOfOrder
309			}
310			if s.At.After(latest) {
311				latest = s.At
312			}
313		}
314		r.ensureStatsLocked()
315		for _, s := range samples {
316			r.fileLocked(s.At, s.Value)
317		}
318		if r.hasAny && r.latest.After(latest) {
319			latest = r.latest
320		}
321		r.latest = latest
322		r.hasAny = true
323		return nil
324	}
325	
326	// fileLocked folds one sample into its window. The caller must hold mu
327	// and must already have cleared the non-finite and out-of-order checks.
328	func (r *Roller) fileLocked(at time.Time, value float64) {
329		start := r.startOf(at)
330		n := len(r.buckets)
331		switch {
332		case n == 0:
333			r.buckets = append(r.buckets, newBucket(start, value))
334			r.bstats = append(r.bstats, seedStats(value))
335		case !start.Before(r.buckets[n-1].Start):
336			// The common case: the sample lands in the newest window or
337			// just past it, so the sorted order is maintained for free.
338			if r.buckets[n-1].Start.Equal(start) {
339				addTo(&r.buckets[n-1], &r.bstats[n-1], value)
340			} else {
341				r.buckets = append(r.buckets, newBucket(start, value))
342				r.bstats = append(r.bstats, seedStats(value))
343			}
344		default:
345			// The sample belongs to an older window, which can only happen
346			// after a merge brought in windows past latest. A window that
347			// already exists is updated in place; a new one goes into the
348			// backfill map, so inserting it never shifts the sorted tail of
349			// buckets and the cost of a mass backfill stays linear in the
350			// number of windows accepted.
351			if i, ok := windowIndex(r.buckets, start); ok {
352				addTo(&r.buckets[i], &r.bstats[i], value)
353			} else if bw, ok := r.back[start]; ok {
354				addTo(&bw.w, &bw.st, value)
355				r.back[start] = bw
356			} else {
357				if r.back == nil {
358					r.back = make(map[time.Time]backWindow)
359				}
360				r.back[start] = backWindow{w: newBucket(start, value), st: seedStats(value)}
361				r.maybeFlushBack()
362			}
363		}
364	}
365	
366	// newBucket returns a window holding a single sample.
367	func newBucket(start time.Time, value float64) Window {
368		return Window{Start: start, Count: 1, Sum: value, Min: value, Max: value}
369	}
370	
371	// maybeFlushBack folds the backfilled windows into buckets once they
372	// number at least half as many as buckets, so the sorting and merge cost
373	// amortizes to constant time per backfilled window. The caller must hold
374	// mu.
375	func (r *Roller) maybeFlushBack() {
376		if len(r.back)*2 < len(r.buckets) {
377			return
378		}
379		bw, bs := r.sortedBackLocked()
380		r.buckets, r.bstats = mergeWindows(r.buckets, r.bstats, bw, bs)
381		r.back = nil
382	}
383	
384	// sortedBackLocked returns the backfilled windows in time order. The
385	// caller must hold mu; the returned slices are fresh and aligned and each
386	// stats owns an independent rational, so the result feeds merging writes.
387	func (r *Roller) sortedBackLocked() ([]Window, []stats) {
388		starts := make([]time.Time, 0, len(r.back))
389		for s := range r.back {
390			starts = append(starts, s)
391		}
392		sort.Slice(starts, func(i, j int) bool {
393			return starts[i].Before(starts[j])
394		})
395		ws := make([]Window, len(starts))
396		ss := make([]stats, len(starts))
397		for i, s := range starts {
398			bw := r.back[s]
399			ws[i] = bw.w
400			ss[i] = cloneStats(bw.st)
401		}
402		return ws, ss
403	}
404	
405	// sortedBackWindowsLocked returns just the backfilled windows in time
406	// order for display reads; their stored Sum/Min/Max already carry the
407	// canonical values, so no bookkeeping is touched.
408	func (r *Roller) sortedBackWindowsLocked() []Window {
409		starts := make([]time.Time, 0, len(r.back))
410		for s := range r.back {
411			starts = append(starts, s)
412		}
413		sort.Slice(starts, func(i, j int) bool {
414			return starts[i].Before(starts[j])
415		})
416		ws := make([]Window, len(starts))
417		for i, s := range starts {
418			ws[i] = r.back[s].w
419		}
420		return ws
421	}
422	
423	// cloneStats returns an independent copy of st, including its accumulator.
424	func cloneStats(st stats) stats {
425		if st.sum != nil {
426			st.sum = new(big.Int).Set(st.sum)
427		}
428		return st
429	}
430	
431	// mergeWindows returns the sorted union of two window sets, each sorted by
432	// window start, combining the statistics of windows that share a start
433	// under the fixed sum and extrema semantics. Windows only one side has are
434	// carried over. The results are always fresh: every returned stats owns an
435	// independent rational, so a later write to either input never reaches the
436	// output. It is a write-path helper for genuinely combining two sets.
437	func mergeWindows(aw []Window, as []stats, bw []Window, bs []stats) ([]Window, []stats) {
438		merged := make([]Window, 0, len(aw)+len(bw))
439		mstats := make([]stats, 0, len(aw)+len(bw))
440		i, j := 0, 0
441		for i < len(aw) && j < len(bw) {
442			switch {
443			case aw[i].Start.Before(bw[j].Start):
444				merged = append(merged, aw[i])
445				mstats = append(mstats, cloneStats(as[i]))
446				i++
447			case bw[j].Start.Before(aw[i].Start):
448				merged = append(merged, bw[j])
449				mstats = append(mstats, cloneStats(bs[j]))
450				j++
451			default:
452				w := aw[i]
453				st := cloneStats(as[i])
454				combineWindow(&w, &st, &bw[j], &bs[j])
455				merged = append(merged, w)
456				mstats = append(mstats, st)
457				i++
458				j++
459			}
460		}
461		for ; i < len(aw); i++ {
462			merged = append(merged, aw[i])
463			mstats = append(mstats, cloneStats(as[i]))
464		}
465		for ; j < len(bw); j++ {
466			merged = append(merged, bw[j])
467			mstats = append(mstats, cloneStats(bs[j]))
468		}
469		return merged, mstats
470	}
471	
472	// Window returns the bucket whose start matches start exactly. The second
473	// result is false when no bucket starts at that instant; no nearby bucket
474	// is substituted. The returned Window is a copy and stays valid no matter
475	// what is filed afterwards.
476	func (r *Roller) Window(start time.Time) (Window, bool) {
477		r.mu.RLock()
478		defer r.mu.RUnlock()
479		if i, ok := windowIndex(r.buckets, start); ok {
480			return r.buckets[i], true
481		}
482		if bw, ok := r.back[start.UTC()]; ok {
483			return bw.w, true
484		}
485		return Window{}, false
486	}
487	
488	// snapshotStatsLocked returns a time-ordered copy of every window and an
489	// independent stats per window, for merging and view derivation. Windows
490	// assembled without bookkeeping (the package's tests build some directly)
491	// are seeded into a local copy, so this stays a pure read even while
492	// holding only an RLock. The caller must hold mu.
493	func (r *Roller) snapshotStatsLocked() ([]Window, []stats) {
494		seeded := r.bstats
495		if len(seeded) < len(r.buckets) {
496			grown := make([]stats, len(r.buckets))
497			copy(grown, r.bstats)
498			for i := len(r.bstats); i < len(r.buckets); i++ {
499				grown[i].absorb(r.buckets[i])
500			}
501			seeded = grown
502		}
503		if len(r.back) == 0 {
504			ws := make([]Window, len(r.buckets))
505			copy(ws, r.buckets)
506			ss := make([]stats, len(seeded))
507			for i := range seeded {
508				ss[i] = cloneStats(seeded[i])
509			}
510			return ws, ss
511		}
512		bw, bs := r.sortedBackLocked()
513		return mergeWindows(r.buckets, seeded, bw, bs)
514	}
515	
516	// Windows returns all buckets in time order. An empty roller yields an
517	// empty slice. The result is a snapshot of one moment: samples filed after
518	// the call do not alter it.
519	func (r *Roller) Windows() []Window {
520		r.mu.RLock()
521		defer r.mu.RUnlock()
522		if len(r.back) == 0 {
523			out := make([]Window, len(r.buckets))
524			copy(out, r.buckets)
525			return out
526		}
527		return r.sortedUnionWindowsLocked()
528	}
529	
530	// sortedUnionWindowsLocked interleaves buckets and the backfill map in
531	// time order. The two sets hold disjoint starts, so windows are only
532	// copied, never recombined. The caller must hold mu.
533	func (r *Roller) sortedUnionWindowsLocked() []Window {
534		back := r.sortedBackWindowsLocked()
535		merged := make([]Window, 0, len(r.buckets)+len(back))
536		i, j := 0, 0
537		for i < len(r.buckets) && j < len(back) {
538			if r.buckets[i].Start.Before(back[j].Start) {
539				merged = append(merged, r.buckets[i])
540				i++
541			} else {
542				merged = append(merged, back[j])
543				j++
544			}
545		}
546		merged = append(merged, r.buckets[i:]...)
547		merged = append(merged, back[j:]...)
548		return merged
549	}
550	
551	// Range returns the buckets that overlap the half-open interval
552	// [from, to), in time order. The endpoints are attributed to windows by
553	// the same epoch-aligned, left-closed rule Add uses: the first bucket
554	// returned is the one containing from, and a bucket starting exactly at
555	// to is excluded. An interval whose end does not come after its start
556	// yields an empty slice, as does an interval no bucket overlaps. The
557	// result is a snapshot of one moment: samples filed after the call do not
558	// alter it.
559	func (r *Roller) Range(from, to time.Time) []Window {
560		r.mu.RLock()
561		defer r.mu.RUnlock()
562		out := []Window{}
563		if !from.Before(to) {
564			return out
565		}
566		var back []Window
567		if len(r.back) != 0 {
568			back = r.sortedBackWindowsLocked()
569		}
570		lo := r.startOf(from)
571		i, _ := windowIndex(r.buckets, lo)
572		j, _ := windowIndex(back, lo)
573		for {
574			var w Window
575			switch {
576			case i < len(r.buckets) && (j >= len(back) || r.buckets[i].Start.Before(back[j].Start)):
577				w = r.buckets[i]
578				i++
579			case j < len(back):
580				w = back[j]
581				j++
582			default:
583				return out
584			}
585			if !w.Start.Before(to) {
586				return out
587			}
588			out = append(out, w)
589		}
590	}
591	
592	// Cursor reads a fixed range of windows in batches. The windows are
593	// snapshot when the cursor is created: samples filed, backfilled, or
594	// merged in afterwards do not alter what the cursor returns, so batched
595	// iteration over a large range never tears, skips, or repeats a window,
596	// and the end of the range is reached deterministically no matter what is
597	// written while the cursor advances.
598	//
599	// A Cursor is safe to advance from multiple goroutines at once; each
600	// batch is handed out exactly once.
601	type Cursor struct {
602		// mu guards pos. windows is fixed at creation and read without the
603		// lock.
604		mu      sync.Mutex
605		windows []Window
606		pos     int
607	}
608	
609	// Cursor returns a cursor over the buckets overlapping the half-open
610	// interval [from, to), selected by the same rule as Range.
611	func (r *Roller) Cursor(from, to time.Time) *Cursor {
612		return &Cursor{windows: r.Range(from, to)}
613	}
614	
615	// Next returns the next batch of up to n windows, in time order. Batches
616	// are consecutive and non-overlapping: together they cover exactly the
617	// windows in the cursor's range. Once the range is exhausted, Next
618	// returns an empty slice and the cursor does not move. A non-positive n
619	// yields an empty slice and does not advance the cursor.
620	func (c *Cursor) Next(n int) []Window {
621		c.mu.Lock()
622		defer c.mu.Unlock()
623		rest := len(c.windows) - c.pos
624		if n <= 0 || rest == 0 {
625			return []Window{}
626		}
627		if n > rest {
628			n = rest
629		}
630		out := make([]Window, n)
631		copy(out, c.windows[c.pos:c.pos+n])
632		c.pos += n
633		return out
634	}
635	
636	// Merge folds other's buckets into this roller: counts and sums combine,
637	// minimums take the smaller, maximums take the larger, and buckets only one
638	// side has are carried over as-is. Merging does not affect out-of-order
639	// tracking. It panics with "rollup: nil roller" if other is nil, and
640	// returns ErrWindowMismatch, leaving this roller unchanged, if the window
641	// sizes differ.
642	//
643	// The merge is atomic with respect to every other call on either roller:
644	// concurrent readers see this roller wholly before or wholly after the
645	// merge, and a sample filed into other while the merge runs is either
646	// folded in completely or not at all. If the two rollers merge each other
647	// at the same time, the outcome matches some serial order of the two
648	// merges; neither is lost.
649	func (r *Roller) Merge(other *Roller) error {
650		if other == nil {
651			panic("rollup: nil roller")
652		}
653		if other.window != r.window {
654			return ErrWindowMismatch
655		}
656		if r == other {
657			r.mu.Lock()
658			defer r.mu.Unlock()
659			r.ensureStatsLocked()
660			if len(r.back) != 0 {
661				bw, bs := r.sortedBackLocked()
662				r.buckets, r.bstats = mergeWindows(r.buckets, r.bstats, bw, bs)
663				r.back = nil
664			}
665			for i := range r.buckets {
666				w := &r.buckets[i]
667				st := &r.bstats[i]
668				w.Count = satAdd(w.Count, w.Count)
669				st.double()
670				w.Sum = st.canonicalSum()
671				w.Min = canonicalMin(w.Min, st.negZero)
672				w.Max = canonicalMax(w.Max, st.negZero, st.posZero)
673			}
674			return nil
675		}
676		// Lock both rollers in ID order so simultaneous merges in
677		// opposite directions cannot deadlock.
678		first, second := r, other
679		if other.id < r.id {
680			first, second = other, r
681		}
682		first.mu.Lock()
683		second.mu.Lock()
684		defer second.mu.Unlock()
685		defer first.mu.Unlock()
686	
687		r.ensureStatsLocked()
688		other.ensureStatsLocked()
689	
690		switch {
691		case len(other.buckets) == 0 && len(other.back) == 0:
692			return nil
693		case len(r.buckets) == 0 && len(r.back) == 0:
694			r.buckets, r.bstats = other.snapshotStatsLocked()
695			return nil
696		}
697		var left, right []Window
698		var lst, rst []stats
699		left, lst = r.buckets, r.bstats
700		if len(r.back) != 0 {
701			bw, bs := r.sortedBackLocked()
702			left, lst = mergeWindows(r.buckets, r.bstats, bw, bs)
703		}
704		right, rst = other.buckets, other.bstats
705		if len(other.back) != 0 {
706			bw, bs := other.sortedBackLocked()
707			right, rst = mergeWindows(other.buckets, other.bstats, bw, bs)
708		}
709		// Both sides are sorted by window start, so the merge is one linear
710		// pass and one backing array, no per-bucket copies or lookups.
711		r.buckets, r.bstats = mergeWindows(left, lst, right, rst)
712		r.back = nil
713		return nil
714	}
715	
716	// satAdd returns a + b saturated at math.MaxInt64 instead of overflowing.
717	func satAdd(a, b int64) int64 {
718		if b > math.MaxInt64-a {
719			return math.MaxInt64
720		}
721		return a + b
722	}
