9	func TestWindowAlignment(t *testing.T) {
10		r := New(10 * time.Second)
11		// Boundaries are left-closed, right-open: a sample exactly at a window
12		// end belongs to the next window.
13		for _, at := range []time.Time{
14			time.Unix(0, 0),
15			time.Unix(5, 0),
16			time.Unix(9, 0),
17		} {
