	stop := make(chan struct{})
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
				_, _ = s.Snapshot()
			}
		}
	}()
	wg.Wait()
	close(stop)
	got, card := s.Snapshot()
	if card.AcceptedSeries != 6 {
		t.Fatalf("accepted = %d, want 6", card.AcceptedSeries)
	}
	var total int64
	for _, sw := range got {
		for _, w := range sw.Windows {
			total += w.Count
		}
	}
