	defer s.mu.Unlock()
	key := keyOf(sample.Labels)
	target, newOverflowOrigin := s.routeLocked(key, sample.Labels)
	if target == nil {
		// Reject policy and no slot for this distinct series. Nothing is
		// filed, so the sample itself is the one rejection counted.
		s.rejected = satAdd(s.rejected, 1)
		return ErrSeriesLimit
	}
	if err := target.roller.Add(sample.At, sample.Value); err != nil {
		// A rejected sample registers neither a series nor an overflow
		// origin, so the roster is unchanged on failure.
		return err
	}
	if newOverflowOrigin {
		s.overflowed[key] = struct{}{}
	}
	return nil
}

// routeLocked decides which roller a sample of an existing or freshly
// seen series goes to, admitting the series or merging it into the
// overflow bucket on first contact. The second result is true only when
// the caller must register key as a new overflow origin once the sample
// is actually filed. A nil target means the reject policy refuses the
// series. The caller must hold mu.
func (s *SeriesSet) routeLocked(key seriesKey, labels map[string]string) (target *seriesState, newOrigin bool) {
	if st, ok := s.series[key]; ok {
		return st, false
	}
	if _, ok := s.overflowed[key]; ok {
		return s.overflow, false
	}
	if len(s.order) < s.maxSeries {
		st := s.newStateLocked(labels)
		s.series[key] = st
		s.order = append(s.order, key)
		return st, false
	}
	if s.policy == OverflowReject {
		return nil, false
	}
	if s.overflow == nil {
