	groups := make(map[*seriesState][]Sample)
	groupOrder := make([]*seriesState, 0)
	targetOf := make(map[seriesKey]*seriesState, len(newKeys))
	for _, key := range admit {
		st := s.newStateLocked(newLabels[key])
		targetOf[key] = st
	}
