	// order of their first appearance, before touching any state.
	newKeys := make([]seriesKey, 0)
	newLabels := make(map[seriesKey]map[string]string)
	plan := make([]seriesKey, len(samples))
	for i, sm := range samples {
		key := keyOf(sm.Labels)
		plan[i] = key
		if _, ok := s.series[key]; ok {
			continue
		}
		if _, ok := s.overflowed[key]; ok {
			continue
		}
		if _, ok := newLabels[key]; ok {
			continue
		}
		newLabels[key] = copyLabels(sm.Labels)
		newKeys = append(newKeys, key)
	}

	free := s.maxSeries - len(s.order)
	if free < 0 {
		free = 0
	}
	admit := newKeys
	var overflowKeys []seriesKey
	if len(newKeys) > free {
		admit = newKeys[:free]
		overflowKeys = newKeys[free:]
		if s.policy == OverflowReject {
			// The batch never takes effect, so no rejection is counted.
			return ErrSeriesLimit
		}
	}

	// Groups collect each target roller's samples in batch order.
	groups := make(map[*seriesState][]Sample)
	groupOrder := make([]*seriesState, 0)
	targetOf := make(map[seriesKey]*seriesState, len(newKeys))
	for _, key := range admit {
		st := s.newStateLocked(newLabels[key])
		targetOf[key] = st
	}
	var overflow *seriesState
	if len(overflowKeys) > 0 {
		if s.overflow == nil {
			s.overflow = &seriesState{labels: map[string]string{}, roller: New(s.window)}
		}
		overflow = s.overflow
	}
	for i, sm := range samples {
		key := plan[i]
		target := s.series[key]
		if target == nil {
			if _, merged := s.overflowed[key]; merged {
				target = s.overflow
			} else if target = targetOf[key]; target == nil {
				target = overflow
			}
		}
		if _, ok := groups[target]; !ok {
			groupOrder = append(groupOrder, target)
		}
		groups[target] = append(groups[target], Sample{At: sm.At, Value: sm.Value})
	}

	// Out-of-order validation runs against the current markers of every
	// roller that already exists; rollers the batch creates have no
	// marker. Nothing has been filed yet, so a failure needs no rollback.
	for _, st := range groupOrder {
		r := st.roller
		if !r.hasAny {
			continue
		}
		for _, sm := range groups[st] {
			if sm.At.Before(r.latest) {
				return ErrOutOfOrder
			}
		}
	}

	// Commit the roster, then file each group. New states are wired in
	// first, so reads holding the lock later in this call cannot observe
	// an empty admitted series.
	for _, key := range admit {
		st := targetOf[key]
		s.series[key] = st
		s.order = append(s.order, key)
	}
	for _, key := range overflowKeys {
		s.overflowed[key] = struct{}{}
	}
	for _, st := range groupOrder {
		if err := st.roller.AddBatch(groups[st]); err != nil {
			// Unreachable after the validation above; AddBatch is
			// all-or-nothing per roller, and earlier groups have already
			// committed. Leave the discrepancy visible rather than silent.
			panic(err)
		}
	}
	return nil
}

// Snapshot returns every series in first-seen order with the overflow
// bucket last, each with its windows in time order, together with the
// cardinality counts measured at the same instant. The result is a
// snapshot of one moment: samples filed after the call do not alter it.
func (s *SeriesSet) Snapshot() ([]SeriesWindow, CardinalityReport) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.snapshotLocked()
}

// snapshotLocked builds the read result. The caller must hold mu, at
// least for reading; every label map and window slice in the result is a
// fresh copy.
func (s *SeriesSet) snapshotLocked() ([]SeriesWindow, CardinalityReport) {
	out := make([]SeriesWindow, 0, len(s.order)+1)
	for _, key := range s.order {
		st := s.series[key]
		out = append(out, SeriesWindow{
			Labels:  copyLabels(st.labels),
			Windows: st.roller.Windows(),
		})
	}
	if len(s.overflowed) > 0 {
		out = append(out, SeriesWindow{
			Labels:   map[string]string{},
			Overflow: true,
			Windows:  s.overflow.roller.Windows(),
		})
	}
	report := CardinalityReport{
		AcceptedSeries:  len(s.order),
		OverflowSeries:  len(s.overflowed),
		RejectedSamples: s.rejected,
	}
	return out, report
}

